using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEngine;

#pragma warning disable 0649 // fields are filled by JsonUtility
namespace Dravio.Character.Editor
{
    /// <summary>
    /// Reader for Assets/Dravio/Character/Data/species-character-spec.json, which is generated by
    /// scripts/art/character/build_species_spec.py from the canonical biology and catalog. Read-only.
    /// </summary>
    [Serializable]
    internal sealed class SpeciesCharacterSpec
    {
        internal const string Path = "Assets/Dravio/Character/Data/species-character-spec.json";

        [Serializable] internal sealed class Palette { public string primary, secondary, belly, accent; }
        [Serializable] internal sealed class Canonical
        {
            public string silhouetteVi; public string[] locomotion; public string protection; public string respiration;
            public string bodyStyle; public string rarity; public int growthMinutes; public Palette palette;
        }
        [Serializable] internal sealed class Rig { public bool walkingLimbs; public bool flightWings; }
        [Serializable] internal sealed class Stage { public string stage; public string growthWindow; public int startsAtGrowthSeconds; public string status; public string assetName; public string prototypeAsset; }
        [Serializable] internal sealed class Species { public string id; public Canonical canonical; public Rig rig; public Stage[] stages; public string[] openQuestions; }

        public int version;
        public Species[] species = new Species[0];

        private static SpeciesCharacterSpec cached;

        internal static SpeciesCharacterSpec Load()
        {
            if (cached != null) return cached;
            if (!File.Exists(Path)) throw new FileNotFoundException("Species character spec missing; run build_species_spec.py", Path);
            cached = JsonUtility.FromJson<SpeciesCharacterSpec>(File.ReadAllText(Path));
            return cached;
        }

        internal static Species Find(string id)
        {
            return Load().species.FirstOrDefault(s => s.id == id);
        }

        [MenuItem("Dravio/Character/Log Species Character Spec")]
        private static void LogMenu()
        {
            cached = null;
            var spec = Load();
            foreach (var s in spec.species)
            {
                Debug.Log("Dravio species " + s.id + ": " + s.canonical.silhouetteVi
                          + " | locomotion=" + string.Join(",", s.canonical.locomotion)
                          + " | surface=" + s.canonical.protection + " | body=" + s.canonical.bodyStyle
                          + " | walkingLimbs=" + s.rig.walkingLimbs + " flightWings=" + s.rig.flightWings
                          + " | stages: " + string.Join(", ", s.stages.Select(x => x.stage + "=" + x.status).ToArray())
                          + (s.openQuestions.Length > 0 ? "\n  open: " + string.Join("\n  open: ", s.openQuestions) : ""));
            }
            Debug.Log("Dravio species spec: " + spec.species.Length + " species. Stage morphology is unspecified in the canonical data.");
        }
    }
}
